fn rotate(a: &[i32], offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new(); // Return an empty array if input is empty
    }
    
    // Calculate effective offset
    let effective_offset = offset % n;
    
    // Create a new vector for the result
    let mut result = vec![0; n];
    
    // Fill the result array with rotated values
    for i in 0..n {
        result[i] = a[(i + effective_offset) % n];
    }
    
    result
}